// 页面组件树静态分析：算出懒加载分割点，并校验基础可访问性规则
const page = {
  type: 'Layout',
  children: [
    { type: 'Header', props: { role: 'banner' } },
    { type: 'Main', children: [
      { type: 'PostList', props: { defer: true } },
      { type: 'CommentBox', props: { defer: true } },
      { type: 'img', props: { src: '/a.png' } },
      { type: 'button', props: {} },
      { type: 'button', props: { 'aria-label': 'close' } },
    ] },
    { type: 'Footer' },
  ],
};

function walk(node, out) {
  out.push(node);
  for (const c of node.children || []) walk(c, out);
  return out;
}
function lazyChunks(root) {
  return walk(root, []).filter(n => n.props && n.props.defer).map(n => n.type);
}
function a11yViolations(root) {
  const v = [];
  for (const n of walk(root, [])) {
    const p = n.props || {};
    if (n.type === 'img' && !p.alt) v.push({ rule: 'img-alt', detail: 'missing alt attribute' });
    if (n.type === 'button') {
      const hasName = !!(p['aria-label'] || p['aria-labelledby'] || n.text);
      if (!hasName) v.push({ rule: 'button-name', detail: 'no accessible name' });
    }
  }
  return v;
}

console.log('lazy_chunks=' + lazyChunks(page).join(','));
console.log('total_nodes=' + walk(page, []).length);
const v = a11yViolations(page);
console.log('a11y_violations=' + v.length);
console.log('rules=' + v.map(x => x.rule).join(','));
console.log('img_alt_violation=' + v.some(x => x.rule === 'img-alt'));
console.log('button_name_violation=' + v.some(x => x.rule === 'button-name'));
